<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $cities=mysqli_query($conn,"SELECT DISTINCT city FROM customers ORDER BY city");$r=false;$error="";if($_SERVER['REQUEST_METHOD']=='POST'){$city=trim($_POST['city']??'');if($city==''||strlen($city)>50)$error="Please select a valid city.";else{$city=mysqli_real_escape_string($conn,$city);$r=mysqli_query($conn,"SELECT id,name,email,city,salary FROM customers WHERE city='$city' ORDER BY name ASC");}} ?>
<h2>Customers By City</h2><form method="POST" class="row g-2 my-3"><div class="col-sm-5"><select name="city" class="form-select" required><option value="">Choose City</option><?php while($c=mysqli_fetch_assoc($cities)): ?><option value="<?php echo htmlspecialchars($c['city']); ?>"><?php echo htmlspecialchars($c['city']); ?></option><?php endwhile; ?></select></div><div class="col-sm-3"><button class="btn btn-primary">Show Customers</button></div></form><?php if($error): ?><div class="alert alert-warning"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($r): ?><div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-dark"><tr><th>ID</th><th>Name</th><th>Email</th><th>City</th><th>Salary</th></tr></thead><tbody><?php if(mysqli_num_rows($r)>0): while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo htmlspecialchars($x['email']); ?></td><td><?php echo htmlspecialchars($x['city']); ?></td><td><?php echo number_format($x['salary'],2); ?></td></tr><?php endwhile; else: ?><tr><td colspan="5">No customers in this city.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>